```python
import os
from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_layout_from_document(document_path: str) -> dict:
    endpoint = os.getenv("AZURE_FORM_RECOGNIZER_ENDPOINT")
    key = os.getenv("AZURE_FORM_RECOGNIZER_KEY")
    model_id = "prebuilt-layout"

    document_analysis_client = DocumentAnalysisClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(document_path, "rb") as f:
        poller = document_analysis_client.begin_analyze_document(
            model_id=model_id, document=f
        )

    result = poller.result()

    layout_elements = {
        "pages": [],
        "tables": [],
        "paragraphs": [],
        "lines": [],
        "words": []
    }

    for page in result.pages:
        page_data = {
            "page_number": page.page_number,
            "width": page.width,
            "height": page.height,
            "angle": page.angle,
            "unit": page.unit,
            "words": [],
            "lines": []
        }

        for word in page.words:
            page_data["words"].append({
                "content": word.content,
                "polygon": word.polygon,
                "confidence": word.confidence
            })

        for line in page.lines:
            page_data["lines"].append({
                "content": line.content,
                "polygon": line.polygon,
                "words": [word.content for word in line.words]
            })

        layout_elements["pages"].append(page_data)

    for table in result.tables:
        table_data = {
            "row_count": table.row_count,
            "column_count": table.column_count,
            "cells": []
        }

        for cell in table.cells:
            table_data["cells"].append({
                "row_index": cell.row_index,
                "column_index": cell.column_index,
                "content": cell.content,
                "polygon": cell.polygon,
                "confidence": cell.confidence,
                "row_span": cell.row_span,
                "column_span": cell.column_span
            })

        layout_elements["tables"].append(table_data)

    for paragraph in result.paragraphs:
        layout_elements["paragraphs"].append({
            "content": paragraph.content,
            "polygon": paragraph.polygon,
            "confidence": paragraph.confidence,
            "role": paragraph.role
        })

    for line in result.pages[0].lines if result.pages else []:
        layout_elements["lines"].append({
            "content": line.content,
            "polygon": line.polygon
        })

    for word in result.pages[0].words if result.pages else []:
        layout_elements["words"].append({
            "content": word.content,
            "polygon": word.polygon,
            "confidence": word.confidence
        })

    return layout_elements
